(function(){
if(window.__QMES_RECIPE_CHEM_MASTER_V4__)return;window.__QMES_RECIPE_CHEM_MASTER_V4__=true;
const KEY='qmes-bom-local-v1';let host=null,nativeHost=null,selectedId=null;const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const load=()=>{try{const x=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(x)?x:[]}catch(e){return[]}};const save=x=>localStorage.setItem(KEY,JSON.stringify(x));
function workOrders(){try{if(typeof DB==='undefined')return[];const docs=DB.woDocs||{};return Object.keys(docs).map(lot=>{const w=docs[lot]||{},b=(DB.batches||[]).find(x=>String(x.no||'')===String(lot))||{};return{lot,item:String(w.item||b.item||DB.lots?.[lot]?.itemName||''),plan:Number(w.plan||b.plan||0),unit:w.unit||b.unit||'kg',date:String(w.date||b.due||'').slice(0,10),tank:w.tank||b.tank||'',customer:w.customer||w.client||'',inputs:Array.isArray(w.inputs)?w.inputs:[],conds:Array.isArray(w.conds)?w.conds:[]}}).filter(x=>x.item)}catch(e){return[]}}
function nextRecipe(){const n=load().length+1;return'RCP-'+String(n).padStart(3,'0')}
function formulaRows(r){const a=r?.formula||[];if(!a.length)return'<tr><td colspan="12" style="text-align:center;color:#94a3b8;padding:24px">작업지시서를 선택하면 투입원료가 자동 작성됩니다.</td></tr>';return a.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.code||'')}</td><td>${esc(x.name)}</td><td>${esc(x.type||'원료')}</td><td>${esc(x.grade||'')}</td><td>${esc(x.ratio)}</td><td>${esc(x.std)}</td><td>${esc(x.tolerance||'±1%')}</td><td>${i+1}</td><td>${esc(x.process||'')}</td><td>${esc(x.ctq||'-')}</td><td>${esc(x.alt||'-')}</td></tr>`).join('')}
function html(){return`<div class="qmes-business-extension"><div class="qbe-title-row"><div><h1 class="qbe-title">Recipe / BOM Master</h1><div class="qbe-subtitle">기존 작업지시서에서 제품 · 기준량 · 투입원료를 자동 불러와 BOM 초안을 생성합니다.</div></div></div><div class="qbe-card" style="padding:10px 12px"><div style="display:flex;gap:7px;align-items:center;flex-wrap:wrap"><button class="qbe-primary" data-a="import">작업지시서에서 BOM 생성</button><select id="qbm-wo" style="min-width:330px;padding:9px;border:1px solid #cbd5e1;border-radius:7px"><option value="">작업지시서 선택</option></select><button class="qbe-primary" data-a="save">저장</button><button class="qbe-primary" data-a="revision" style="background:#f59e0b">BOM 개정</button><button class="qbe-primary" data-a="print" style="background:#475569">인쇄</button><span id="qbm-msg" style="font-size:12px;font-weight:800;color:#2563eb"></span></div></div><div style="display:grid;grid-template-columns:.6fr 1.4fr;gap:12px"><div class="qbe-card"><div class="qbe-card-head"><h2>제품 목록</h2></div><div class="qbe-table-wrap"><table><thead><tr><th>제품코드/품목</th><th>Recipe</th></tr></thead><tbody id="qbm-products"></tbody></table></div></div><div class="qbe-card"><div class="qbe-card-head"><h2>BOM / Revision 목록</h2></div><div class="qbe-table-wrap"><table><thead><tr><th>Revision</th><th>생성기준 LOT</th><th>기준 Batch</th><th>적용일</th><th>상태</th></tr></thead><tbody id="qbm-revs"></tbody></table></div></div></div><div class="qbe-card"><div class="qbe-card-head"><h2>선택 BOM 기본정보</h2><span class="qbe-hint">자동작성 항목은 수정 가능</span></div><div class="qbe-form-grid"><div class="qbe-field"><label>제품코드 / 품목</label><input data-f="productCode"></div><div class="qbe-field"><label>제품명</label><input data-f="productName"></div><div class="qbe-field"><label>생성기준 작업지시 LOT</label><input data-f="sourceLot" readonly></div><div class="qbe-field"><label>설비</label><input data-f="tank"></div><div class="qbe-field"><label>Recipe No.</label><input data-f="recipeNo"></div><div class="qbe-field"><label>Revision</label><input data-f="revision"></div><div class="qbe-field"><label>기준 Batch Size (kg)</label><input data-f="batchSize" type="number"></div><div class="qbe-field"><label>예상 수율 (%)</label><input data-f="yield" type="number"></div><div class="qbe-field"><label>적용일</label><input data-f="effectiveDate" type="date"></div><div class="qbe-field"><label>상태</label><select data-f="status"><option>작성중</option><option>검토중</option><option>승인</option><option>사용중</option><option>폐기</option></select></div><div class="qbe-field"><label>변경내용</label><input data-f="changeNote"></div><div class="qbe-field"><label>작성 / 검토 / 승인</label><input readonly placeholder="전자결재 연동"></div></div></div><div class="qbe-card"><div class="qbe-card-head"><h2>표준 배합표 (Formula)</h2><span class="qbe-hint" id="qbm-total">작업지시 투입원료 자동 연동</span></div><div class="qbe-table-wrap"><table><thead><tr><th>순번</th><th>원료코드</th><th>원료명</th><th>구분</th><th>Grade</th><th>배합비 %</th><th>기준량 kg</th><th>허용오차</th><th>투입순서</th><th>투입공정</th><th>CTQ</th><th>대체원료</th></tr></thead><tbody id="qbm-formula"></tbody></table></div></div><div class="qbe-card"><div class="qbe-card-head"><h2>공정조건</h2><span class="qbe-hint">작업지시 조건 자동 연동</span></div><div class="qbe-table-wrap"><table><thead><tr><th>순서</th><th>관리항목</th><th>기준값</th><th>실적값</th></tr></thead><tbody id="qbm-conds"><tr><td colspan="4" style="text-align:center;color:#94a3b8;padding:20px">작업지시서를 선택하면 자동 작성됩니다.</td></tr></tbody></table></div></div></div>`}
function msg(t,c='#2563eb'){const e=host.querySelector('#qbm-msg');e.textContent=t;e.style.color=c}
function getFields(){const o={};host.querySelectorAll('[data-f]').forEach(e=>o[e.dataset.f]=e.value.trim());return o}function setFields(r={}){host.querySelectorAll('[data-f]').forEach(e=>e.value=r[e.dataset.f]||'')}
function populateWO(){const s=host.querySelector('#qbm-wo');s.innerHTML='<option value="">작업지시서 선택</option>'+workOrders().map(w=>`<option value="${esc(w.lot)}">${esc(w.lot)} · ${esc(w.item)} · ${w.plan.toLocaleString()} ${esc(w.unit)}</option>`).join('')}
function draftFromWO(lot){const w=workOrders().find(x=>x.lot===lot);if(!w){msg('작업지시서를 선택하세요.','#dc2626');return}const total=w.inputs.reduce((a,x)=>a+(Number(x.std)||0),0)||w.plan||0;const existing=load().find(x=>x.productCode===w.item);const formula=w.inputs.map((x,i)=>{const std=Number(x.std)||0;return{name:x.name||x.material||'',code:x.code||x.materialCode||'',type:(typeof qmesMaterialType==='function'?qmesMaterialType(x.name):'원료'),std,ratio:total?Number((std/total*100).toFixed(4)):0,tolerance:'±1%',process:x.process||'',ctq:x.ctq||'-',alt:'-'}});const r={id:'BOM-'+Date.now(),productCode:w.item,productName:w.item,sourceLot:w.lot,tank:w.tank,recipeNo:existing?.recipeNo||nextRecipe(),revision:existing?.revision||'Rev.01',batchSize:String(total||w.plan||''),yield:'100',effectiveDate:w.date||new Date().toISOString().slice(0,10),status:'작성중',changeNote:existing?'작업지시서 기준 BOM 초안 재생성':'작업지시서 기준 최초 BOM 생성',formula,conds:w.conds||[]};selectedId=r.id;setFields(r);host.querySelector('#qbm-formula').innerHTML=formulaRows(r);renderConds(r);host.__draft=r;msg(`${w.lot} 작업지시서에서 BOM 초안을 자동 작성했습니다.`,'#15803d')}
function renderConds(r){const b=host.querySelector('#qbm-conds'),a=r?.conds||[];b.innerHTML=a.length?a.map((x,i)=>`<tr><td>${i+1}</td><td>${esc(x.name||x.label||'')}</td><td>${esc(x.std||x.target||x.spec||'')}</td><td>${esc(x.act||'-')}</td></tr>`).join(''):'<tr><td colspan="4" style="text-align:center;color:#94a3b8;padding:20px">등록된 공정조건이 없습니다.</td></tr>'}
function render(){const a=load(),p=host.querySelector('#qbm-products'),r=host.querySelector('#qbm-revs');p.innerHTML=a.length?a.map(x=>`<tr data-id="${esc(x.id)}" style="cursor:pointer"><td>${esc(x.productCode)}</td><td>${esc(x.recipeNo)}</td></tr>`).join(''):'<tr><td colspan="2" style="text-align:center;color:#94a3b8;padding:20px">저장된 BOM이 없습니다.</td></tr>';r.innerHTML=a.length?a.map(x=>`<tr data-id="${esc(x.id)}" style="cursor:pointer"><td>${esc(x.revision)}</td><td>${esc(x.sourceLot||'-')}</td><td>${esc(x.batchSize)}</td><td>${esc(x.effectiveDate)}</td><td>${esc(x.status)}</td></tr>`).join(''):'<tr><td colspan="5" style="text-align:center;color:#94a3b8;padding:20px">저장된 Revision이 없습니다.</td></tr>'}
function select(id){const x=load().find(v=>v.id===id);if(!x)return;selectedId=id;host.__draft=x;setFields(x);host.querySelector('#qbm-formula').innerHTML=formulaRows(x);renderConds(x);msg('저장된 BOM을 불러왔습니다.')}
function saveDraft(){let d=host.__draft||{};const f=getFields();if(!f.productCode||!f.recipeNo){msg('먼저 작업지시서에서 BOM을 생성하세요.','#dc2626');return}d={...d,...f,id:selectedId||d.id||'BOM-'+Date.now()};let a=load(),i=a.findIndex(x=>x.id===d.id);if(i>=0)a[i]=d;else a.unshift(d);save(a);selectedId=d.id;host.__draft=d;render();msg('BOM 초안을 저장했습니다.','#15803d')}
function revision(){if(!host.__draft){msg('개정할 BOM을 선택하세요.','#dc2626');return}const s=host.__draft,n=(parseInt(String(s.revision).replace(/\D/g,''),10)||0)+1,d={...s,id:'BOM-'+Date.now(),revision:'Rev.'+String(n).padStart(2,'0'),status:'작성중',changeNote:'BOM 개정',effectiveDate:new Date().toISOString().slice(0,10)};selectedId=d.id;host.__draft=d;setFields(d);msg(`${d.revision} 개정 초안을 만들었습니다.`,'#15803d')}
function wire(){host.addEventListener('click',e=>{const tr=e.target.closest('[data-id]');if(tr){select(tr.dataset.id);return}const b=e.target.closest('[data-a]');if(!b)return;if(b.dataset.a==='import')draftFromWO(host.querySelector('#qbm-wo').value);if(b.dataset.a==='save')saveDraft();if(b.dataset.a==='revision')revision();if(b.dataset.a==='print')window.print()})}
function mount(){const h=document.getElementById('qmes-business-extension-host');if(!h||!h.querySelector('.qbe-title,h1')?.textContent.includes('Recipe / BOM Master'))return;if(host&&document.body.contains(host))return;nativeHost=h;host=document.createElement('div');host.id='qmes-chemical-bom-v4-host';host.innerHTML=html();h.parentNode.insertBefore(host,h);h.style.display='none';wire();populateWO();render()}
function unmount(){if(!host)return;const active=document.querySelector('[data-qbe-menu="recipe"] .qmes-top-menu-button.is-active,[data-qbe-menu="recipe"] button.is-active');if(!active){host.remove();host=null;if(nativeHost&&document.body.contains(nativeHost))nativeHost.style.removeProperty('display');nativeHost=null}}
new MutationObserver(()=>{mount();unmount()}).observe(document.documentElement,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});document.addEventListener('click',e=>{if(e.target.closest('[data-qbe-menu="recipe"]'))setTimeout(mount,100);else if(e.target.closest('.qmes-top-menu-button'))setTimeout(unmount,100)},true);setInterval(()=>{mount();if(host)populateWO()},1200);
})();